		require.Equal(t, connector.GetTeamsToLogins()[0].KubeUsers, r.GetKubeUsers(types.Allow))
		require.Len(t, mappings[0].KubeGroups, 0)
		require.Len(t, mappings[0].KubeUsers, 0)

	return role
